{
  "case_id": "xsu_sg_007_work_stopped_due_to_impairment",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Konklusionen om, at arbejdsophør ikke i sig selv giver ret, er korrekt. Men svaret tilføjer en forkert eller uunderstøttet påstand: at UDK vurderer, om ansøgeren kan opfylde aktiverings- og jobsøgningskrav ved kontanthjælp eller førtidspension. Det er ikke i kilderne. Svaret fremstiller desuden vurderingen som en generel vurdering af 'særlig stor begrænsning' og ikke som en vurdering af arbejdets karakter og muligheden for andet arbejde."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "Ingen af de tre kritiske elementer er med. Svaret nævner ikke, at arbejdets karakter sammenholdes med funktionsnedsættelsen. Det nævner ikke, at sagens øvrige oplysninger bruges til at vurdere andre typer arbejde. Det nævner ikke skånehensyn eller mindre omfang. Det siger kun generelt, at evnen til at opnå og beholde arbejde vurderes."
    },
    "c03_direct_relevance": {
      "label": "not_met",
      "reason": "Svaret besvarer første del (ikke i sig selv ret). Anden del, hvad UDK vurderer ved arbejdsophør, besvares med generiske formuleringer og irrelevant materiale om aktivering og jobsøgning ved kontanthjælp eller førtidspension. Den specifikke vurdering mangler."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som lovbestemmelse, bekendtgørelse eller vejledning."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten til påstandene kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer, at UDK tager stilling til muligheden for at efterkomme aktiverings- og jobsøgningskrav ved kontanthjælp eller førtidspension. Det har ingen støtte i de udleverede kilder. Formuleringen om, at begrænsningen 'i sig selv berettiger', er heller ikke understøttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "Svaret gengiver, at arbejdsophør ikke i sig selv giver ret. Det mangler dog, at oplysningen om ophør er udgangspunkt for en nærmere vurdering, og at fysisk ikke-belastende arbejde kun er et eksempel. Skånehensyn og mindre omfang er heller ikke med."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende. Konklusionen om, at ophør ikke er nok og at der kræves varig og særlig stor begrænsning, følger af de anførte trin."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret siger, at UDK 'vil' tage stilling til aktiverings- og jobsøgningskrav, som om det var en fast regel uden støtte. Det siger også, at begrænsningen 'i sig selv berettiger', hvilket skævvrider vurderingens karakter."
    }
  },
  "xhaile_coverage": {
    "A22": {
      "label": "partial",
      "reason": "Svaret behandler arbejdsophør på grund af funktionsnedsættelse og siger, at det ikke i sig selv giver ret. Men det beskriver ikke, at arbejdets karakter vurderes i forhold til funktionsnedsættelsen, eller at gener og skånebehov inddrages."
    },
    "A23": {
      "label": "no",
      "reason": "Svaret nævner ikke, at UDK vurderer, om ansøgeren kan varetage andre typer arbejde, eventuelt med skånehensyn eller i mindre omfang. Det omtaler kun generelt evnen til at opnå og beholde arbejde."
    }
  },
  "overall_notes": "Svaret har den rigtige hovedkonklusion, men udelader kernen i vurderingen (arbejdets karakter, andre jobtyper, skånehensyn og mindre omfang), tilføjer uunderstøttet indhold om aktivering og jobsøgning og angiver ingen kilder."
}

